const readingStatsForUser = `-- name: ReadingStatsForUser :one
SELECT
  count(*) FILTER (WHERE finished_on IS NOT NULL AND NOT dnf)::bigint AS books_finished,
  count(*) FILTER (WHERE dnf)::bigint                                 AS books_dnf,
  count(*) FILTER (WHERE finished_on IS NULL AND NOT dnf)::bigint     AS books_in_progress,
  coalesce(sum(progress_bp) FILTER (WHERE finished_on IS NULL AND NOT dnf), 0)::bigint AS open_progress_bp
FROM reading_sessions
WHERE user_id = $1
`

type ReadingStatsForUserRow struct {
	BooksFinished   int64 `json:"books_finished"`
	BooksDnf        int64 `json:"books_dnf"`
	BooksInProgress int64 `json:"books_in_progress"`
	OpenProgressBp  int64 `json:"open_progress_bp"`
}

func (q *Queries) ReadingStatsForUser(ctx context.Context, userID uuid.UUID) (ReadingStatsForUserRow, error) {
	row := q.db.QueryRow(ctx, readingStatsForUser, userID)
	var i ReadingStatsForUserRow
	err := row.Scan(
		&i.BooksFinished,
		&i.BooksDnf,
		&i.BooksInProgress,
		&i.OpenProgressBp,
	)
	return i, err
}

