const removeWorkFromUserShelves = `-- name: RemoveWorkFromUserShelves :execrows
DELETE FROM shelf_items
 WHERE work_id = $1
   AND shelf_id IN (SELECT s.id FROM shelves s
                     WHERE s.user_id = $2
                       AND s.kind IN ('want_to_read', 'reading', 'read', 'dnf')
                       AND s.kind <> $3)
`

type RemoveWorkFromUserShelvesParams struct {
	WorkID   uuid.UUID `json:"work_id"`
	UserID   uuid.UUID `json:"user_id"`
	KeepKind ShelfKind `json:"keep_kind"`
}

// Moving a book between reading states must not leave it on two shelves at
// once ("Currently Reading" and "Read" simultaneously is a data bug, not a
// user preference). Favorites is exempt: it is orthogonal to reading state.
func (q *Queries) RemoveWorkFromUserShelves(ctx context.Context, arg RemoveWorkFromUserShelvesParams) (int64, error) {
	result, err := q.db.Exec(ctx, removeWorkFromUserShelves, arg.WorkID, arg.UserID, arg.KeepKind)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const startReread = `-- name: StartReread :one
INSERT INTO reading_sessions (user_id, work_id, edition_id, format, started_on, progress_bp)
VALUES ($1, $2, $3, $4, CURRENT_DATE, 0)
RETURNING id, user_id, work_id, edition_id, format, started_on, finished_on, dnf, progress_bp, created_at, updated_at
`

type StartRereadParams struct {
	UserID    uuid.UUID      `json:"user_id"`
	WorkID    uuid.UUID      `json:"work_id"`
	EditionID pgtype.UUID    `json:"edition_id"`
	Format    NullReadFormat `json:"format"`
}

// Closes any open session, then opens a fresh one: a reread is a new row, never
// a mutation of history.
func (q *Queries) StartReread(ctx context.Context, arg StartRereadParams) (ReadingSession, error) {
	row := q.db.QueryRow(ctx, startReread,
		arg.UserID,
		arg.WorkID,
		arg.EditionID,
		arg.Format,
	)
	var i ReadingSession
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.WorkID,
		&i.EditionID,
		&i.Format,
		&i.StartedOn,
		&i.FinishedOn,
		&i.Dnf,
		&i.ProgressBp,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

