const upsertReadingProgress = `-- name: UpsertReadingProgress :one

INSERT INTO reading_sessions (user_id, work_id, edition_id, format, started_on, progress_bp)
VALUES ($1, $2, $3, $4,
        CURRENT_DATE, $5)
ON CONFLICT (user_id, work_id) WHERE finished_on IS NULL AND NOT dnf
DO UPDATE SET
  progress_bp = EXCLUDED.progress_bp,
  edition_id  = COALESCE(EXCLUDED.edition_id, reading_sessions.edition_id),
  format      = COALESCE(EXCLUDED.format, reading_sessions.format),
  finished_on = CASE WHEN EXCLUDED.progress_bp >= 10000 THEN CURRENT_DATE ELSE NULL END
RETURNING id, user_id, work_id, edition_id, format, started_on, finished_on, dnf, progress_bp, created_at, updated_at
`

type UpsertReadingProgressParams struct {
	UserID     uuid.UUID      `json:"user_id"`
	WorkID     uuid.UUID      `json:"work_id"`
	EditionID  pgtype.UUID    `json:"edition_id"`
	Format     NullReadFormat `json:"format"`
	ProgressBp int32          `json:"progress_bp"`
}

// ---- Reading sessions -------------------------------------------------------
// Upserts the single open session for (user, work). Reaching 100% closes it and
// stamps the finish date; the partial unique index guarantees one open session.
func (q *Queries) UpsertReadingProgress(ctx context.Context, arg UpsertReadingProgressParams) (ReadingSession, error) {
	row := q.db.QueryRow(ctx, upsertReadingProgress,
		arg.UserID,
		arg.WorkID,
		arg.EditionID,
		arg.Format,
		arg.ProgressBp,
	)
	var i ReadingSession
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.WorkID,
		&i.EditionID,
		&i.Format,
		&i.StartedOn,
		&i.FinishedOn,
		&i.Dnf,
		&i.ProgressBp,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
